{
  "root": "main_stack",
  "state": {
    "grandSlamEvents": [
      {
        "name": "Australian Open",
        "location": "Melbourne, Australia",
        "dates": "January 13 – 26, 2025",
        "surface": "Hard Court",
        "icon": "../assets/r_000225_01_1_trophy.svg"
      },
      {
        "name": "French Open (Roland Garros)",
        "location": "Paris, France",
        "dates": "May 25 – June 8, 2025",
        "surface": "Clay Court",
        "icon": "../assets/r_000225_01_1_trophy.svg"
      },
      {
        "name": "Wimbledon",
        "location": "London, England",
        "dates": "June 30 – July 13, 2025",
        "surface": "Grass Court",
        "icon": "../assets/r_000225_01_1_trophy.svg"
      },
      {
        "name": "US Open",
        "location": "New York, USA",
        "dates": "August 25 – September 7, 2025",
        "surface": "Hard Court",
        "icon": "../assets/r_000225_01_1_trophy.svg"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_overview",
        "intro_text",
        "key_events_title",
        "grand_slam_table",
        "quick_actions_title",
        "atp_button",
        "wta_button",
        "sources_title",
        "atp_source_button",
        "wta_source_button"
      ]
    },
    "title_overview": {
      "type": "Text",
      "props": {
        "text": "2025 Grand Slam Tennis Schedule Overview",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "The four major international tennis tournaments, known as the Grand Slams, are held annually across the globe, bringing together the world's top players. While exact dates are subject to official confirmation, the tournaments generally follow a consistent schedule each year.",
        "variant": "body"
      },
      "children": []
    },
    "key_events_title": {
      "type": "Text",
      "props": {
        "text": "Key 2025 Grand Slam Events",
        "variant": "h2"
      },
      "children": []
    },
    "grand_slam_table": {
      "type": "Table",
      "props": {
        "statePath": "/grandSlamEvents",
        "columns": [
          {
            "key": "name",
            "label": "Tournament"
          },
          {
            "key": "location",
            "label": "Location"
          },
          {
            "key": "dates",
            "label": "Dates"
          },
          {
            "key": "surface",
            "label": "Surface"
          },
          {
            "key": "icon",
            "label": "Icon",
            "type": "icon"
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "name",
        "highlightColumns": [
          "dates",
          "surface"
        ]
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "atp_button": {
      "type": "Button",
      "props": {
        "label": "ATP Tour Official Site"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.atptour.com/"
          }
        }
      },
      "children": []
    },
    "wta_button": {
      "type": "Button",
      "props": {
        "label": "WTA Tour Official Site"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.wtatennis.com/"
          }
        }
      },
      "children": []
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "atp_source_button": {
      "type": "Button",
      "props": {
        "label": "ATP Tour"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.atptour.com/"
          }
        }
      },
      "children": []
    },
    "wta_source_button": {
      "type": "Button",
      "props": {
        "label": "WTA Tour"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.wtatennis.com/"
          }
        }
      },
      "children": []
    }
  }
}
